<script>
 import { createEventDispatcher } from 'svelte';
 import { GripVertical, ArrowUpRight, Clock3 } from 'lucide-svelte';
 import { threads } from '../data.js';
 export let scenes=[];
 export let selected=1;
 const dispatch=createEventDispatcher();
 let dragging=null;
 let over=null;
 function drop(id){if(dragging!==null&&dragging!==id)dispatch('reorder',{from:dragging,to:id});dragging=null;over=null;}
</script>
<div class="timeline-list"><div class="timeline-top"><Clock3 size={13}/><span>STORY ORDER</span><span>Drag to reorder</span></div>{#each scenes as scene,i}<div class="timeline-row" class:over={over===scene.id} class:selected={selected===scene.id} draggable="true" ondragstart={(e)=>{dragging=scene.id;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(scene.id));}} ondragover={(e)=>{e.preventDefault();over=scene.id;}} ondragleave={()=>over=null} ondragend={()=>{dragging=null;over=null;}} ondrop={(e)=>{e.preventDefault();drop(scene.id);}} role="group" aria-label={`Scene ${i+1}: ${scene.title}`}><span class="number">{String(i+1).padStart(2,'0')}</span><div class="track"><span style:background={threads.find(t=>t.id===scene.thread)?.color||threads[0].color}></span></div><button class="timeline-scene" onclick={()=>dispatch('select',scene.id)}><div class="scene-info"><span style:color={threads.find(t=>t.id===scene.thread)?.color||threads[0].color}>{threads.find(t=>t.id===scene.thread)?.name||threads[0].name}</span><h3>{scene.title}</h3><p>{scene.location||'Location not set'}<span>·</span>{scene.choices.length} {scene.choices.length===1?'choice':'choices'}</p></div><ArrowUpRight size={16}/></button><div class="reorder"><button aria-label={`Move ${scene.title} earlier`} disabled={i===0} onclick={()=>dispatch('reorder',{from:scene.id,to:scenes[i-1].id})}>↑</button><button aria-label={`Move ${scene.title} later`} disabled={i===scenes.length-1} onclick={()=>dispatch('reorder',{from:scene.id,to:scenes[i+1].id})}>↓</button></div><GripVertical class="drag-handle" size={15}/></div>{/each}</div>
<style>.timeline-top{display:flex;align-items:center;gap:8px;color:#767a86;font-size:12px;letter-spacing:1.2px;padding:0 8px 20px}.timeline-top>span:last-child{margin-left:auto;font-size:12px;letter-spacing:0}.timeline-row{display:flex;align-items:stretch;gap:15px;position:relative}.number{color:#646a76;font-variant-numeric:tabular-nums;font-size:12px;padding-top:29px;width:20px}.track{position:relative;width:10px;display:flex;justify-content:center;padding-top:31px;flex-shrink:0}.track:before{position:absolute;content:'';width:1px;background:#ffffff0e;inset:0 auto}.timeline-row:last-child .track:before{bottom:50%}.timeline-row:first-of-type .track:before{top:32px}.track>span{height:7px;width:7px;position:relative;border-radius:50%;box-shadow:0 0 0 5px #191d22}.timeline-scene{display:flex;align-items:center;justify-content:space-between;flex:1;min-width:0;border:1px solid #ffffff0c;background:#ffffff03;border-radius:9px;padding:18px 20px;margin-bottom:15px;text-align:left;color:#858a96;transition:background .2s,border-color .2s;cursor:pointer}.timeline-scene:hover{background:#ffffff07;border-color:#ffffff22}.scene-info{min-width:0}.scene-info>span{font-size:12px;letter-spacing:.5px}.scene-info h3{font-size:16px;color:#d9dce2;font-weight:500;letter-spacing:-.2px;margin:8px 0 7px}.scene-info p{font-size:12px;color:#717782;margin:0;display:flex;gap:9px;align-items:center}.scene-info p>span{color:#454c56}.selected .timeline-scene{border-color:#b7a4e052;background:#ad9bd508}.over .timeline-scene{border-color:#b4a5df;background:#ad9bd51a}.reorder{display:flex;flex-direction:column;justify-content:center;gap:2px;margin-top:-14px}.reorder button{background:transparent;border:0;border-radius:4px;color:#78808e;cursor:pointer;padding:4px}.reorder button:hover{background:#fff1;color:#e2def0}.reorder button:disabled{opacity:.2;cursor:default}:global(.drag-handle){align-self:center;color:#48515d;margin-top:-14px;cursor:grab}@media(max-width:550px){.timeline-row{gap:8px}.timeline-scene{padding:15px 13px}.scene-info h3{font-size:14px}.scene-info p{font-size:12px;flex-wrap:wrap;gap:5px}.track{width:6px}.number{font-size:12px;width:16px}.reorder{display:none}}</style>
